/* From Uiverse.io by Yaya12085 - Tags: card */
.__UIV_SCOPE__ .pack_card {
  position: relative;
  display: flex;
  flex-direction: column;
  border-radius: 0.5rem;
  border: 2px solid rgb(99 102 241);
  padding: 1.5rem 1rem 1rem 1rem;
  margin-top: 1rem;
  background-color: #fff;
  max-width: 300px;
}

.__UIV_SCOPE__ .banner {
  position: absolute;
  left: 0px;
  right: 0px;
  top: -2rem;
  display: flex;
  justify-content: center;
}

.__UIV_SCOPE__ .banner_tag {
  display: flex;
  height: 1.5rem;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  background-color: rgb(99 102 241);
  padding: 0.25rem 0.75rem;
  font-size: 0.75rem;
  line-height: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: #fff;
}

.__UIV_SCOPE__ .pack_name {
  margin-bottom: 0.5rem;
  text-align: center;
  font-size: 1.5rem;
  line-height: 2rem;
  font-weight: 700;
  color: rgb(31 41 55 );
}

.__UIV_SCOPE__ .description {
  margin: 0 auto 2rem auto;
  text-align: center;
  color: rgb(107 114 128 );
}

.__UIV_SCOPE__ .lists > :not([hidden]) ~ :not([hidden]) {
  margin-top: 0.5rem;
}

.__UIV_SCOPE__ .list {
  display: flex;
  gap: 0.5rem;
}

.__UIV_SCOPE__ .list svg {
  height: 1.5rem;
  width: 1.5rem;
  flex-shrink: 0;
  color: rgb(99 102 241 );
}

.__UIV_SCOPE__ .list span {
  color: rgb( 75 85 99 );
}

.__UIV_SCOPE__ .bottom {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.__UIV_SCOPE__ .price_container {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 0.25rem;
}

.__UIV_SCOPE__ .devise {
  align-self: flex-start;
  color: rgb( 75 85 99 );
}

.__UIV_SCOPE__ .price {
  font-size: 2.25rem;
  line-height: 2.5rem;
  font-weight: 700;
  color: rgb(31 41 55 );
}

.__UIV_SCOPE__ .date {
  color: rgb(107 114 128 );
}

.__UIV_SCOPE__ .btn {
  display: block;
  border-radius: 0.5rem;
  background-color: rgb(99 102 241 );
  padding: 0.75rem 2rem;
  text-align: center;
  font-size: 0.875rem;
  line-height: 1.25rem;
  font-weight: 600;
  color: #fff;
  outline: 2px solid transparent;
  outline-offset: 2px;
  transition: all .1s cubic-bezier(0.4, 0, 0.2, 1);
}

.__UIV_SCOPE__ .btn:hover {
  background-color: rgb(79 70 229 );
}

.__UIV_SCOPE__ .btn:active {
  background-color: rgb(67 56 202 );
}
